<?php use Passport\Copy; ?>
<p class="eyebrow"><?= $e($t('STEWARDSHIP · PRIVATE')) ?></p><h1><?= $e($t('requests')) ?></h1><p><?= $e($t('Review specific consent before approving any use. Counteroffers must be communicated to the requester using their email. Record the agreed final demo fee when approving.')) ?></p><?php if (!$requests): ?><p class="empty"><?= $e($t('empty')) ?></p><?php endif ?>
<?php foreach ($requests as $request): ?><article class="card request-card"><div class="card-top"><a class="mono" href="/dashboard/stories/<?= $e($request['storyId']) ?>"><?= $e($request['storyId']) ?></a><span class="badge"><?= $e($request['status']) ?></span></div><h2><?= $e($request['requesterName']) ?></h2><a href="mailto:<?= $e($request['requesterContact']) ?>"><?= $e($request['requesterContact']) ?></a><p class="preserve"><?= $e($request['intendedUse']) ?></p><p><?= $e($request['isCommercial'] ? $t('Commercial use') : $t('Noncommercial use')) ?> · <?= $e($money($request['proposedFeeMinor'] ?? 0, $request['currency'])) ?> <?= $e($t('proposed')) ?></p><?php if ($request['isAiTraining']): ?><p class="notice warning"><?= $e(Copy::AI) ?></p><?php endif ?><?php if ($request['counterFeeMinor'] !== null): ?><p><?= $e($t('Counteroffer')) ?>: <?= $e($money($request['counterFeeMinor'], $request['currency'])) ?></p><?php endif ?><?php if ($request['decisionNote']): ?><p><?= $e(\Passport\Copy::ledgerNote($request['decisionNote'])) ?></p><?php endif ?>
<?php if (in_array($request['status'], ['PENDING','COUNTERED'], true)): ?><form data-api="/api/requests/<?= $e($request['id']) ?>" data-method="PATCH" data-reload><div class="two"><label><?= $e($t('Decision')) ?><select name="status"><option value="APPROVED"><?= $e($t('Approve')) ?></option><option value="DECLINED"><?= $e($t('Decline')) ?></option><option value="COUNTERED"><?= $e($t('Counter')) ?></option></select></label><label><?= $e($t('Final demo fee (minor units)')) ?><input type="number" name="finalFeeMinor" min="0" max="1000000000" step="1" value="<?= $e($request['counterFeeMinor'] ?? $request['proposedFeeMinor'] ?? 0) ?>" data-int></label></div><label><?= $e($t('Counteroffer demo fee (minor units)')) ?><input type="number" name="counterFeeMinor" min="0" max="1000000000" step="1" data-int></label><label><?= $e($t('Decision note (required for a counteroffer)')) ?><textarea name="note" maxlength="2000"></textarea></label><label class="check"><input type="checkbox" name="feeConfirmed"> <?= $e($t('For approval, I confirm the final demo fee agreed with the requester (zero means no fee).')) ?></label><button class="button"><?= $e($t('Record decision')) ?></button><p class="form-message" role="status" aria-live="polite"></p></form><?php endif ?></article><?php endforeach ?>


